@page "/courses"
@rendermode InteractiveServer
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search by title or code..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

@{
    var courses = CatalogService.GetCourses(searchTerm, selectedDepartmentId > 0 ? selectedDepartmentId : null);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <div class="row">
        @foreach (var course in courses)
        {
            <div class="col-md-6 mb-3">
                <div class="card course-card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.Title</h5>
                        <span class="badge bg-secondary">@course.Code</span>
                        <span class="badge bg-info text-dark">@course.Credits Credits</span>
                        <p class="card-text mt-2 text-muted">@course.DepartmentName</p>
                        <p class="card-text">@course.Schedule</p>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                        <a href="/enroll?courseId=@course.Id" class="btn btn-outline-success btn-sm ms-2">Enroll</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private string? searchTerm;
    private int selectedDepartmentId;

    [SupplyParameterFromQuery]
    public int? departmentId { get; set; }

    protected override void OnInitialized()
    {
        if (departmentId.HasValue)
        {
            selectedDepartmentId = departmentId.Value;
        }
    }
}

@page "/enroll"
@rendermode InteractiveServer
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@model.StudentName</strong>. Your enrollment request for <strong>@GetCourseName(model.CourseId)</strong> has been received.</p>
        <p>You will receive a confirmation at your university email address.</p>
        <hr>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-6">
            <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger mb-3" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
                    <ValidationMessage For="() => model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" placeholder="e.g., AB123456" />
                    <ValidationMessage For="() => model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseSelect" class="form-label">Course</label>
                    <InputSelect id="courseSelect" class="form-select" @bind-Value="model.CourseId">
                        <option value="0">-- Select a course --</option>
                        @foreach (var course in CatalogService.GetCourses())
                        {
                            <option value="@course.Id">@course.Code - @course.Title</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.CourseId" />
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    private UniversityCourseCatalog.Models.EnrollmentRequest model = new();
    private bool submitted;

    [SupplyParameterFromQuery]
    public int? courseId { get; set; }

    protected override void OnInitialized()
    {
        if (courseId.HasValue && courseId.Value > 0)
        {
            model.CourseId = courseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var result = CatalogService.SubmitEnrollmentRequest(model);
        if (result)
        {
            submitted = true;
        }
    }

    private string GetCourseName(int id)
    {
        var course = CatalogService.GetCourse(id);
        return course is not null ? $"{course.Code} - {course.Title}" : "Unknown Course";
    }
}

