 @page "/enroll"
 @rendermode InteractiveServer
 @inject UniversityCourseCatalog.Services.ICatalogService CatalogService

 <PageTitle>Enroll - University Course Catalog</PageTitle>

 <h1 class="mb-4">Enrollment Request</h1>

 @if (submitted)
 {
     <div class="alert alert-success">
         <h4 class="alert-heading">Enrollment Request Submitted!</h4>
         <p>Thank you, <strong>@model.StudentName</strong>. Your enrollment request for <strong>@GetCourseName(model.CourseId)</strong> has been received.</p>
         <p>You will receive a confirmation at your university email address.</p>
         <hr>
         <a href="/courses" class="btn btn-primary">Browse More Courses</a>
     </div>
 }
 else
 {
     <div class="row">
         <div class="col-md-6">
             <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                 <DataAnnotationsValidator />
                 <ValidationSummary class="text-danger mb-3" />

                 <div class="mb-3">
                     <label for="studentName" class="form-label">Full Name</label>
                     <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
                     <ValidationMessage For="() => model.StudentName" />
                 </div>

                 <div class="mb-3">
                     <label for="studentId" class="form-label">Student ID</label>
                     <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" placeholder="e.g., AB123456" />
                     <ValidationMessage For="() => model.StudentId" />
                 </div>

                 <div class="mb-3">
                     <label for="courseSelect" class="form-label">Course</label>
                     <InputSelect id="courseSelect" class="form-select" @bind-Value="model.CourseId">
                         <option value="0">-- Select a course --</option>
                         @foreach (var course in CatalogService.GetCourses())
                         {
                             <option value="@course.Id">@course.Code - @course.Title</option>
                         }
                     </InputSelect>
                     <ValidationMessage For="() => model.CourseId" />
                 </div>

                 <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
             </EditForm>
         </div>
     </div>
 }

 @code {
     private UniversityCourseCatalog.Models.EnrollmentRequest model = new();
     private bool submitted;

     [SupplyParameterFromQuery]
     public int? courseId { get; set; }

     protected override void OnInitialized()
     {
         if (courseId.HasValue && courseId.Value > 0)
         {
             model.CourseId = courseId.Value;
         }
     }

     private void HandleSubmit()
     {
         var result = CatalogService.SubmitEnrollmentRequest(model);
         if (result)
         {
             submitted = true;
         }
     }

     private string GetCourseName(int id)
     {
         var course = CatalogService.GetCourse(id);
         return course is not null ? $"{course.Code} - {course.Title}" : "Unknown Course";
     }
 }

